/**
 * 后续 Run 使用的显式强度；空值表示使用模型默认开启档位。
 */
reasoning_effort?: ReasoningEffortKey,
/**
 * Session 当前是活动还是归档状态。
 */
lifecycle: SessionLifecycle,
/**
 * Session 的持久产品角色；旧快照安全缺省为普通会话。
 */
