/**
 * 后续 Run 捕获的当前审批模式。
 */
approval_mode: ApprovalMode,
/**
 * 创建 Session 时冻结的 Workspace 绑定；`None` 表示普通未绑定会话。
 */
workspace_id?: WorkspaceId | null,
/**
 * 当前活动 Run；Session 空闲时为 `None`。
 */
active_run_id: RunId | null,
/**
 * 规范 Conversation 中已经完整提交的消息数量。
 */
