/**
 * 发起 clear/compact 时使用的当前权威 Conversation generation。
 */
conversation_generation: number, composer_capabilities: ComposerCapabilitiesSnapshot, work_plan: WorkPlanSnapshot | null, goal: GoalSnapshot | null, active_run: RunSnapshot | null, queue: QueueSnapshot, approvals: ApprovalQueueSnapshot, attachments: Array<AttachmentSummary>, file_references: Array<ConversationFileReference>,
/**
 * 只包含明确声明且尚未撤销的交付项；文件可用性由 Host 读取时校验。
 */
